"""Hierarchical Platt scaling."""

def __init__(self):
    self.eps = 1e-6
    self.global_coef_ = (1.0, 0.0)
    self.group_coefs_ = {}

def fit(self, probs, labels, groups=None):
    probs = np.asarray(probs).reshape(-1)
    labels = np.asarray(labels).reshape(-1).astype(int)
    logits = special.logit(np.clip(probs, self.eps, 1.0 - self.eps))

    def loss_fn(a, b, m_logits, m_labels):
        p = special.expit(a * m_logits + b)
        p = np.clip(p, self.eps, 1.0 - self.eps)
        return float(-np.mean(m_labels * np.log(p) + (1 - m_labels) * np.log(1 - p)))

    def obj_global(x):
        return loss_fn(float(x[0]), float(x[1]), logits, labels)

    res_global = optimize.minimize(obj_global, x0=np.array([1.0, 0.0]), method="L-BFGS-B", bounds=[(0.01, 10.0), (-10.0, 10.0)])
    self.global_coef_ = tuple(res_global.x) if res_global.success else (1.0, 0.0)

    if groups is not None:
        groups = np.asarray(groups).reshape(-1)
        for g in np.unique(groups):
            mask = groups == g
            if mask.sum() < 5 or np.unique(labels[mask]).size < 2:
                self.group_coefs_[int(g)] = self.global_coef_
                continue

            def obj_group(x):
                l = loss_fn(float(x[0]), float(x[1]), logits[mask], labels[mask])
                reg = 0.1 * ((float(x[0]) - self.global_coef_[0])**2 + (float(x[1]) - self.global_coef_[1])**2)
                return l + reg

            res_g = optimize.minimize(obj_group, x0=np.array(self.global_coef_), method="L-BFGS-B", bounds=[(0.01, 10.0), (-10.0, 10.0)])
            self.group_coefs_[int(g)] = tuple(res_g.x) if res_g.success else self.global_coef_

    return self

def predict_proba(self, probs, groups=None):
    probs = np.asarray(probs).reshape(-1)
    logits = special.logit(np.clip(probs, self.eps, 1.0 - self.eps))

    if groups is None:
        a, b = self.global_coef_
        out = special.expit(a * logits + b)
    else:
        groups = np.asarray(groups).reshape(-1)
        out = np.empty_like(probs)
        for g in np.unique(groups):
            mask = groups == g
            a, b = self.group_coefs_.get(int(g), self.global_coef_)
            out[mask] = special.expit(a * logits[mask] + b)

    return np.clip(out, self.eps, 1.0 - self.eps)

